//=============================================================================
// Testbench for the 2-context context-switching prototype
// (design/snowflake/snowflake_core_ctx2.sv, generated by fpga_flow/make_ctx2.py).
//
// Both contexts are driven with the SAME 12-round stimulus as the single
// context tests, and the trace is written PER CONTEXT
// (rtl_trace_ctx0.txt / rtl_trace_ctx1.txt) in exactly the format the golden
// trace uses, so snowflake_sim/ref/compare_trace.py can check each context
// independently.  That proves three things at once:
//   * the two state copies are independent (per-context trace matches localuf),
//   * the shared datapath really is time multiplexed (contexts interleave),
//   * per-context commit events are correct.
//=============================================================================
`timescale 1ns / 1ps
`include "../../design/generated/snowflake_graph.svh"

// ---- stall injection delay (context 0's syndrome arrives late) --------------
// xvlog's .bat wrapper eats the '=' in "-d NAME=value", so the delay is picked
// with marker defines; a value-carrying -d still wins if the flow supports it.
`ifdef SNOW_STALL_D100
  `define SNOW_STALL_DELAY 100
`elsif SNOW_STALL_D60
  `define SNOW_STALL_DELAY 60
`elsif SNOW_STALL_D40
  `define SNOW_STALL_DELAY 40
`elsif SNOW_STALL_D20
  `define SNOW_STALL_DELAY 20
`elsif SNOW_STALL_D10
  `define SNOW_STALL_DELAY 10
`endif
`ifndef SNOW_STALL_DELAY
  `define SNOW_STALL_DELAY 6
`endif

module tb_snowflake_pe_array_ctx;

`ifdef SNOW_CTX1
  // equivalence anchor: run the 2-context RTL with a single context.  If the
  // trace then matches the single-context core, the restructuring (views,
  // write-back, FSM) is correct and any mismatch at NCTX=2 comes from the
  // context index arithmetic.
  localparam integer NCTX = 1;
`else
  localparam integer NCTX = 2;
`endif
  localparam integer NCYC = 12;      // rounds, same as the single-context test
`ifdef SNOW_ONE_ONE
  localparam integer ONE_ONE = 1;
`else
  localparam integer ONE_ONE = 0;
`endif

  reg clk = 0;
  always #5 clk = ~clk;              // 10 ns
  integer clk_cnt = 0;
  always @(posedge clk) clk_cnt = clk_cnt + 1;

  reg reset = 1;
  reg [NCTX-1:0] start = 0;
  reg [NCTX*SNOW_NSYN-1:0] syndrome = 0;
  wire [NCTX-1:0] done;
  wire all_busy;
  wire [NCTX*SNOW_NCOMMIT-1:0] commit_onehot;
  wire [SNOW_NN*SNOW_CID_W-1:0] obs_cid;
  wire [SNOW_NN-1:0] obs_active, obs_whole, obs_defect, obs_grown, obs_unrooted, obs_busy;
  wire [SNOW_NN*SNOW_PTR_W-1:0] obs_ptr;
  wire [SNOW_NE*2-1:0] obs_growth;
  wire [SNOW_NE-1:0]   obs_ecorr;
  wire [((NCTX>1)?$clog2(NCTX):1)-1:0] dbg_ctx;
  wire [2:0] dbg_stage;
  wire [7:0] dbg_step;
  wire dbg_valid;

  snowflake_pe_array_ctx #(.ONE_ONE(ONE_ONE), .NCTX(NCTX)) dut (
      .clk(clk), .reset(reset), .start(start), .syndrome(syndrome),
      .done(done), .all_busy(all_busy), .commit_onehot(commit_onehot),
      .obs_cid(obs_cid), .obs_active(obs_active), .obs_whole(obs_whole),
      .obs_defect(obs_defect), .obs_ptr(obs_ptr), .obs_grown(obs_grown),
      .obs_unrooted(obs_unrooted), .obs_busy(obs_busy),
      .obs_growth(obs_growth), .obs_ecorr(obs_ecorr),
      .dbg_ctx(dbg_ctx), .dbg_stage(dbg_stage), .dbg_step(dbg_step), .dbg_valid(dbg_valid)
  );

  function automatic [7:0] ST_CH(input [2:0] s);
    case (s) 3'd1: ST_CH="D"; 3'd2: ST_CH="G"; 3'd3: ST_CH="M";
             3'd4: ST_CH="g"; 3'd5: ST_CH="m"; default: ST_CH="?"; endcase
  endfunction

  integer fd [0:NCTX-1];
  integer cyc, n, e, s, c, guard;
  // done is a one-cycle pulse and the stall scenario has a window where the
  // testbench is not sampling, so count the pulses instead of polling them
  // (polling missed a pulse and looked exactly like an RTL deadlock).
  integer done_count [0:NCTX-1];
  integer c2;
  always @(posedge clk) begin
    for (c2 = 0; c2 < NCTX; c2 = c2 + 1)
      if (done[c2]) done_count[c2] = done_count[c2] + 1;
  end
  integer commit_events [0:NCTX-1];
  reg [NCTX-1:0] done_seen;
  reg [SNOW_NSYN-1:0] rounds [0:NCYC-1];
  reg [SNOW_NSYN-1:0] synd;

  task dump_ctx(input integer ctx);
    integer ptr_val;
    begin
      $fwrite(fd[ctx], "T %0d %s %0d\n", cyc, ST_CH(dbg_stage), dbg_step);
      for (n = 0; n < SNOW_NN; n = n + 1) begin
        ptr_val = obs_ptr[n*SNOW_PTR_W +: SNOW_PTR_W];
        $fwrite(fd[ctx], "N %0d ", n);
        // the RESET sentinel is printed as "R" -- the golden trace and the
        // single-context testbench use the same convention, and without it the
        // comparison reports a false mismatch on every unrooting step
        if (obs_cid[n*SNOW_CID_W +: SNOW_CID_W] == SNOW_RESET_CID) $fwrite(fd[ctx], "R ");
        else $fwrite(fd[ctx], "%0d ", obs_cid[n*SNOW_CID_W +: SNOW_CID_W]);
        $fwrite(fd[ctx], "%0d %0d %0d %0d %0d %0d\n",
                obs_active[n], obs_whole[n], obs_defect[n],
                ptr_val, obs_grown[n], obs_unrooted[n]);
      end
      for (e = 0; e < SNOW_NE; e = e + 1)
        $fwrite(fd[ctx], "E %0d-%0d %0d %0d\n", SNOW_EDGE_U(e), SNOW_EDGE_V(e),
                obs_growth[e*2 +: 2], obs_ecorr[e]);
      for (e = 0; e < SNOW_NE; e = e + 1)
        if (SNOW_IS_COMMIT(e) && commit_onehot[ctx*SNOW_NCOMMIT + SNOW_COMMIT_IDX(e)])
          $fwrite(fd[ctx], "P %0d-%0d\n", SNOW_EDGE_U(e), SNOW_EDGE_V(e));
    end
  endtask

  // Trace sampling runs in its own process: the round loop has windows where it
  // is not executing (the stall delay), and steps inside those windows were
  // silently missing from the trace, which looked like an RTL failure.
  always @(negedge clk) if (dbg_valid) dump_ctx(dbg_ctx);

  initial begin
    rounds[0] = 16'h0000; rounds[1] = 16'h0001; rounds[2] = 16'h0002; rounds[3] = 16'h0003;
    rounds[4] = 16'h0000; rounds[5] = 16'h0001; rounds[6] = 16'h0000; rounds[7] = 16'h0002;
    rounds[8] = 16'h0003; rounds[9] = 16'h0000; rounds[10] = 16'h0001; rounds[11] = 16'h0000;

    fd[0] = $fopen("rtl_trace_ctx0.txt", "w");
    if (NCTX > 1) fd[1] = $fopen("rtl_trace_ctx1.txt", "w");
    if (fd[0] == 0 || (NCTX > 1 && fd[1] == 0)) begin $display("ERROR: cannot open traces"); $finish; end

    reset = 1'b1;
    repeat (5) @(posedge clk);
    reset = 1'b0;
    repeat (2) @(posedge clk);
    for (c = 0; c < NCTX; c = c + 1) done_count[c] = 0;

    for (cyc = 0; cyc < NCYC; cyc = cyc + 1) begin
      synd = rounds[cyc][SNOW_NSYN-1:0];
      syndrome = {NCTX{synd}};
`ifdef SNOW_ONE_CTX
      // stall scenario: only context 1 is ever started, so context 0 stays
      // idle the whole time.  If an idle context really does not consume the
      // shared datapath, this must take as many cycles as NCTX=1 does for the
      // same number of rounds.
      @(negedge clk); start = {{(NCTX-1){1'b0}}, 1'b1};
      @(negedge clk); start = {NCTX{1'b0}};
      done_seen = {NCTX{1'b0}};
      guard = 0;
      while (!(done_count[0] >= cyc+1 && done_count[NCTX-1] >= cyc+1)) begin
        @(negedge clk);
        guard = guard + 1;
        if (guard > 4000) begin
          $display("WATCHDOG: round %0d stuck", cyc);
          $finish;
        end
        for (c = 0; c < NCTX; c = c + 1)
          if (done[c]) done_seen[c] = 1'b1;
      end
`else
`ifdef SNOW_STALL
      // stall-filling scenario: context 1 is requested at t=0, context 0 only
      // SNOW_STALL_DELAY cycles later (as if its syndrome arrived late).  If the
      // arbiter really fills the datapath with the ready context, the total time
      // stays close to the unstalled run instead of growing by delay per round --
      // and both traces must still match localuf.  Both requests are ONE-cycle
      // pulses: a request held high for the whole delay re-triggers the context
      // as soon as it finishes its round, which fabricates extra rounds.
      @(negedge clk); start = {NCTX{1'b0}}; start[1] = 1'b1;
      @(negedge clk); start = {NCTX{1'b0}};
      repeat (`SNOW_STALL_DELAY - 1) @(negedge clk);
      start = {NCTX{1'b0}}; start[0] = 1'b1;
      @(negedge clk); start = {NCTX{1'b0}};
`else
      @(negedge clk); start = {NCTX{1'b1}};
      @(negedge clk); start = {NCTX{1'b0}};
`endif
      done_seen = {NCTX{1'b0}};
      guard = 0;
      while (!(done_count[0] >= cyc+1 && done_count[NCTX-1] >= cyc+1)) begin
        @(negedge clk);
        guard = guard + 1;
        if (guard > 4000) begin
          $display("WATCHDOG: round %0d stuck: done=%b dbg_ctx=%0d dbg_stage=%0d",
                   cyc, done, dbg_ctx, dbg_stage);
          // dump the selected context's state so the stuck node is visible
          for (n = 0; n < SNOW_NN; n = n + 1)
            $display("  stuck n=%0d cid=%0d act=%b whole=%b def=%b ptr=%0d grn=%b unr=%b busy=%b",
                     n, obs_cid[n*SNOW_CID_W +: SNOW_CID_W], obs_active[n], obs_whole[n],
                     obs_defect[n], obs_ptr[n*SNOW_PTR_W +: SNOW_PTR_W], obs_grown[n],
                     obs_unrooted[n], obs_busy[n]);
          for (e = 0; e < SNOW_NE; e = e + 1)
            $display("  stuck e=%0d growth=%0d ecorr=%b", e, obs_growth[e*2 +: 2], obs_ecorr[e]);
          $fclose(fd[0]); $fclose(fd[1]);
          $finish;
        end
        for (c = 0; c < NCTX; c = c + 1)
          if (done[c]) done_seen[c] = 1'b1;
        if (guard < 40)
          $display("[dbg] cyc=%0d g=%0d ctx=%0d stage=%0d obsptr0=%b valid=%b",
                   cyc, guard, dbg_ctx, dbg_stage,
                   obs_ptr[0*SNOW_PTR_W +: SNOW_PTR_W], dbg_valid);
      end
`endif
    end

    for (c = 0; c < NCTX; c = c + 1) $fclose(fd[c]);
    $display("ctx2 trace written (%0d rounds, contexts=%0d, clk_cycles=%0d)", NCYC, NCTX, clk_cnt);
    $finish;
  end

endmodule
